 el.textContent=status.error||`${p.beeps?(status.context==='running'?'Bips ativados':'Bips por ativar'):'Bips desligados'} · ${p.voice?(status.voice?'Voz: '+status.voice:'Voz pt-PT indisponível'):'Voz desligada'}`;
