function savedSource(id){return store.state.saved.find(s=>s.id===id)}
function showHistory(id){const h=store.state.history.find(h=>h.id===id);openModal(`${modalHead(escape(h.plan.name))}<p class="small muted">${date(h.date)} · ${h.status==='completed'?'Concluído':'Terminado antecipadamente'}</p><div class="summary-strip"><span>Ativo: ${formatTime(h.actualSeconds)}</span><span>Programado: ${formatTime(h.plan.duration)}</span></div><p class="small">${h.rating?'★'.repeat(h.rating):'Sem classificação'}<br>${escape(h.notes||'Sem notas.')}</p><div class="details-label">Execução registada</div>${h.plan.blocks.map(b=>`<div style="margin-top:14px"><h3>${escape(b.name)}</h3>${b.items.map(i=>{const steps=h.plan.timeline.filter(t=>t.itemId===i.id&&t.kind!=='rest');const done=steps.filter(t=>h.completedSteps.includes(t.id)).length;const reps=steps.reduce((n,t)=>n+(h.completedReps[t.id]||0),0);return `<p class="small muted">${escape(i.exercise.name)} · ${done}/${i.sets} séries${i.reps?' · '+reps+' rep. confirmadas':''}</p>`}).join('')}</div>`).join('')}<div class="details-label">AMRAP</div><p class="small muted">${Object.values(h.rounds).reduce((a,b)=>a+b,0)} voltas completas confirmadas.</p><div class="details-label">Alterações</div>${h.changes.length?h.changes.map(c=>`<p class="small muted">${formatTime(c.at)} · ${escape(c.reason)}</p>`).join(''):'<p class="small muted">Sem alterações durante a sessão.</p>'}<div class="notice">As repetições são confirmadas pelo utilizador. A contagem guiada indica apenas uma cadência prevista.</div>`)}
app.addEventListener('click',handleClick);content.addEventListener('click',handleClick);
async function handleClick(event){const el=event.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;try{
 if(a==='navigate'){captureConfig();if(page==='counter')pauseCounterPanel(document.getElementById('counter-panel'));if(el.dataset.page==='counter'){audio.stop();if(clock?.running){clock.pause();releaseWake();checkpoint()}}page=el.dataset.page;if(page==='library'){onlyFavorites=false;filter='Todos'}render()}
 else if(a==='settings'||a==='sessionAudio'){if(page==='counter')pauseCounterPanel(document.getElementById('counter-panel'));if(a==='sessionAudio'&&clock.running){clock.pause();audio.stop();releaseWake();checkpoint()}settings()}
 else if(a==='retryStorage'){const ok=store.retry();paintStorageStatus();if(ok)toast('Dados guardados neste dispositivo.')}
 else if(a==='closeModal'){modal.close();editing=null;modalExercise=null}
 else if(a==='duration'){captureConfig();config.minutes=Number(el.dataset.value);render({scroll:false})}
 else if(a==='level'){captureConfig();config.level=Number(el.dataset.value);render({scroll:false})}
 else if(a==='modality'){captureConfig();config.modality=el.dataset.value;render({scroll:false})}
 else if(a==='quick30'||a==='quick20'){config={...config,minutes:a==='quick30'?30:20,modality:a==='quick30'?'Full Body':'Cardio e core',lowImpact:a==='quick20',included:[]};newPlan()}
 else if(a==='favorites'){onlyFavorites=true;filter='Todos';search='';page='library';render()}
 else if(a==='filter'){filter=el.dataset.value;render({scroll:false})}
 else if(a==='demoPhase'){
 const figure=el.closest('.exercise-demo'),exercise=byId[id]||clock?.plan.blocks.flatMap(b=>b.items).find(i=>i.exercise.id===id)?.exercise,entry=movementFor(exercise),phase=Number(el.dataset.phase);
 if(figure&&entry&&Number.isInteger(phase)&&phase>=0&&phase<entry.poses.length){figure.querySelector('.demo-image').innerHTML=movementSvg(exercise,{phase});figure.querySelector('.demo-caption').textContent=entry.labels[phase];figure.querySelectorAll('[data-action="demoPhase"]').forEach(button=>{const selected=Number(button.dataset.phase)===phase;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected))});}
 }
 else if(a==='details')showDetails(id);
 else if(a==='favoriteExercise'){save(s=>{s.favorites=s.favorites.includes(id)?s.favorites.filter(x=>x!==id):[...s.favorites,id]});if(modal.open&&modalExercise)showDetails(id);else render({scroll:false})}
 else if(a==='excludeExercise'){save(s=>{s.excluded=s.excluded.includes(id)?s.excluded.filter(x=>x!==id):[...s.excluded,id]});showDetails(id)}
 else if(a==='edit')editDialog(el.dataset.block,el.dataset.item);
 else if(a==='regenerate'){plan=regenerateBlock(plan,el.dataset.block,store.state);persistPlan();render({scroll:false});toast('Bloco renovado. Duração preservada.')}
 else if(a==='moveUp'||a==='moveDown'){const b=plan.blocks.find(b=>b.id===editing.blockId),i=b.items.findIndex(i=>i.id===editing.itemId),j=i+(a==='moveUp'?-1:1);if(j>=0&&j<b.items.length){[b.items[i],b.items[j]]=[b.items[j],b.items[i]];rebuild(plan);persistPlan();render({scroll:false});toast('Ordem atualizada.')}else toast('O exercício já está no limite da lista.')}
 else if(a==='savePlan'){updatePlanName();if(save(s=>{const at=s.saved.findIndex(p=>p.id===plan.id);if(at<0)s.saved.unshift(structuredClone(plan));else s.saved[at]=structuredClone(plan);s.lastPlan=plan}))toast('Treino guardado no dispositivo.')}
 else if(a==='start'){updatePlanName();if(store.state.session&&!clock){openModal(`${modalHead('Já existe uma sessão')}<p class="small muted">Recupera o treino em pausa ou termina essa sessão antes de iniciar outra.</p>${btn('recover','Recuperar sessão','primary full','style="margin-top:20px"')}${btn('discardSession','Eliminar sessão em pausa','danger full','style="margin-top:10px"')}`)}else{persistPlan();await startSession()}}
 else if(a==='recover'){modal.close();await startSession(true)}
 else if(a==='discardSession'){if(save(s=>{s.session=null})){modal.close();toast('Sessão em pausa eliminada. Podes iniciar o novo treino.')}}
 else if(a==='togglePause'){if(clock.running){clock.pause();audio.stop();releaseWake()}else{const activation=audio.unlock();audio.speak('Vamos continuar.');await activation;clock.resume();requestWake()}checkpoint();paintClock(clock.getSnapshot())}
 else if(a==='nextStep'||a==='previousStep'){const s=clock.getSnapshot();audio.stop();audio.resetCue();if(clock.running)await audio.unlock();if(a==='nextStep'){if(s.index===clock.plan.timeline.length-1){openModal(`${modalHead('Terminar agora?')}<p class="small">O último intervalo ainda não terminou. A sessão será guardada como terminada antecipadamente.</p>${btn('confirmStop','Terminar sessão','danger full','style="margin-top:20px"')}`);clock.pause();audio.stop();releaseWake();checkpoint();return}clock.seek(s.step.end,'Etapa avançada manualmente')}else clock.seek(clock.plan.timeline[Math.max(0,s.index-1)].start,'Etapa anterior repetida');paintedStep='';checkpoint()}
 else if(a==='stop'){clock.pause();audio.stop();releaseWake();checkpoint();openModal(`${modalHead('Por hoje, chega?')}<p class="small muted">Podes guardar a sessão realizada ou continuar de onde ficaste.</p><div class="footer-actions">${btn('closeModal','Continuar','secondary')}${btn('confirmStop','Terminar','danger')}</div>`)}
 else if(a==='confirmStop'){modal.close();finishSession('interrupted')}
 else if(a==='confirmReps'||a==='amrapDone'){const s=clock.getSnapshot(),b=clock.plan.blocks.find(b=>b.id===s.step.blockId),i=a==='amrapDone'?b.items[amrapIndex%b.items.length]:b.items.find(i=>i.id===s.step.itemId);clock.pause();audio.stop();releaseWake();checkpoint();openModal(`${modalHead('Registar execução')}<p class="small muted">${escape(i.exercise.name)}. Regista o que realizaste; a sessão está em pausa.</p><form id="reps-form" data-amrap="${a==='amrapDone'}"><div class="field"><label for="actual-reps">${i.reps?'Repetições realizadas':'Segundos de isometria realizados'}</label><input id="actual-reps" name="reps" type="number" min="0" max="999" required value="${i.reps||i.work}"></div><button class="primary full">Confirmar e retomar</button></form>`)}
 else if(a==='substituteActive'){const s=clock.getSnapshot();if(!s.step.exercise||s.step.kind==='rest'){toast('Substitui durante uma etapa de execução.');return}clock.pause();audio.stop();releaseWake();checkpoint();const alts=alternatives(s.step.exercise,{...clock.plan.config,phase:s.step.kind},store.state.excluded);openModal(`${modalHead('Substituir exercício')}<p class="small muted">Esta série e as seguintes usarão o novo movimento. Os tempos mantêm-se.</p><div class="amrap-list">${alts.length?alts.map(e=>btn('applyActiveSwap',escape(e.name),'secondary',`data-id="${e.id}"`)).join(''):'<p class="small muted">Sem alternativas compatíveis. Podes avançar esta etapa ou manter o movimento.</p>'}</div>`)}
 else if(a==='applyActiveSwap'){const s=clock.getSnapshot(),oldName=s.step.exercise.name;for(const step of clock.plan.timeline)if(step.itemId===s.step.itemId&&step.start>=s.step.start){step.exercise=structuredClone(byId[id]);if(step.kind==='work')Object.assign(step,repetitionTarget(step.exercise,step.duration,clock.plan.config.level))}const item=clock.plan.blocks.find(b=>b.id===s.step.blockId).items.find(i=>i.id===s.step.itemId);item.exercise=structuredClone(byId[id]);Object.assign(item,repetitionTarget(item.exercise,item.work,clock.plan.config.level));clock.changes.push({at:s.elapsed,reason:`Substituição de ${oldName} por ${byId[id].name}`});modal.close();paintedStep='';checkpoint();toast('Exercício substituído. Retoma quando quiseres.')}
 else if(a==='openSaved')usePlan(savedSource(id));
 else if(a==='repeatHistory')usePlan(store.state.history.find(h=>h.id===id).plan);
 else if(a==='variant'){const source=savedSource(id);config={...source.config,included:[]};plan=generate(config,{...store.state,history:[{plan:source},...store.state.history]});plan.name=source.name+' · Variante';usePlan(plan)}
 else if(a==='progression'){const source=structuredClone(savedSource(id));source.id=crypto.randomUUID();source.name+=' · Progressão';for(const b of source.blocks)if(b.type==='main'&&b.format!=='amrap')for(const i of b.items){const shift=Math.min(3,Math.max(0,i.rest-5));i.rest-=shift;i.work+=shift}for(const b of source.blocks)if(b.type==='main')for(const i of b.items)if(i.reps)i.reps+=1;rebuild(source);usePlan(source);toast('Proposta: até +3s de execução e +1 repetição prevista. Revê antes de começar.')}
 else if(a==='favoritePlan'){save(s=>{const p=s.saved.find(p=>p.id===id);p.favorite=!p.favorite});render({scroll:false})}
 else if(a==='deleteSaved'){openModal(`${modalHead('Eliminar este treino?')}<p class="small muted">O histórico de execuções é preservado.</p>${btn('confirmDeleteSaved','Eliminar treino guardado','danger full',`data-id="${id}" style="margin-top:20px"`)}`)}
 else if(a==='confirmDeleteSaved'){save(s=>{s.saved=s.saved.filter(p=>p.id!==id)});modal.close();render({scroll:false})}
 else if(a==='historyDetails')showHistory(id);
 else if(a==='rate'){rating=Number(el.dataset.value);app.querySelectorAll('[data-action="rate"]').forEach(b=>{b.classList.toggle('on',Number(b.dataset.value)<=rating);b.setAttribute('aria-pressed',Number(b.dataset.value)<=rating)})}
 else if(a==='testAudio'){if(page==='active'&&clock?.running){clock.pause();audio.stop();releaseWake();checkpoint();paintClock(clock.getSnapshot())}const activation=audio.unlock();audio.speak('Teste de som. Flexões. Série dois. Quinze repetições.');await activation;const beep=audio.beep('start');paintAudioStatus(audio.status);if(!beep)toast(audio.status.error||'Ativa os bips e aumenta o volume nas definições.');else if(!audio.voice)toast('Bip emitido. A voz pt-PT não está disponível neste navegador.');}
 else if(a==='manageData'){openModal(`${modalHead('Os teus dados')}${backupControls()}`)}
 else if(a==='export'){await exportAllData()}
 else if(a==='importBackup'){document.getElementById('import-file').click()}
 else if(a==='includeExercises'){captureConfig();openModal(`${modalHead('Incluir no próximo treino')}<p class="small muted">Escolhe até 6 movimentos compatíveis com o teu nível e impacto. A seleção respeita os grupos do treino; se não couber, o gerador avisa.</p><form id="include-form"><div style="max-height:50vh;overflow:auto;margin:15px 0">${exercises.filter(e=>categories.indexOf(e.category)<6&&suitableForMain(e,config.level)&&e.difficulty<=config.level&&(!config.lowImpact||e.impact==='low')&&!store.state.excluded.includes(e.id)).map(e=>`<label class="toggle"><span>${escape(e.name)}</span><input type="checkbox" name="include" value="${e.id}" ${config.included.includes(e.id)?'checked':''}></label>`).join('')}</div><button class="primary full">Aplicar seleção</button></form>`)}
 else if(a==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null}
 }catch(err){toast(err.message||'Não foi possível concluir esta ação.');console.error(err)}}
app.addEventListener('submit',submit);content.addEventListener('submit',submit);
async function submit(event){event.preventDefault();const form=event.target,f=new FormData(form);try{
 if(form.id==='config-form'){captureConfig();newPlan()}
 else if(form.id==='edit-form'){const b=plan.blocks.find(b=>b.id===editing.blockId),i=b.items.find(i=>i.id===editing.itemId);const exercise=f.get('exercise')===i.exercise.id?i.exercise:structuredClone(byId[f.get('exercise')]);plan.config.excluded=[...store.state.excluded];plan=editItem(plan,editing.blockId,editing.itemId,{exercise,sets:Number(f.get('sets')),work:Number(f.get('work')),rest:Number(f.get('rest')),reps:f.get('reps')?Number(f.get('reps')):null,locked:f.has('locked')});persistPlan();modal.close();render({scroll:false});toast('Plano atualizado. Duração exata preservada.')}
 else if(form.id==='settings-form'){const stored=save(s=>{s.preferences={...s.preferences,voice:f.has('voice'),beeps:f.has('beeps'),advanceWarning:f.has('advanceWarning'),voiceURI:f.get('voiceURI'),voiceMode:f.get('voiceMode'),voiceVolume:Number(f.get('voiceVolume')),beepVolume:Number(f.get('beepVolume'))}});audio.refreshVoices();modal.close();toast(stored?'Preferências guardadas.':'Preferências aplicadas apenas nesta sessão. Exporta os dados antes de fechar.')}
 else if(form.id==='include-form'){const included=f.getAll('include');if(included.length>6)throw Error('Escolhe no máximo 6 exercícios.');config.included=included;modal.close();render({scroll:false})}
 else if(form.id==='reps-form'){const s=clock.getSnapshot(),n=Number(f.get('reps'));if(!Number.isInteger(n)||n<0||n>999)throw Error('Número de repetições inválido.');if(form.dataset.amrap==='true'){const b=clock.plan.blocks.find(b=>b.id===s.step.blockId);const key=s.step.id+'-movement-'+amrapIndex;clock.completedReps[key]=n;amrapIndex++;if(amrapIndex%b.items.length===0)clock.rounds[s.step.id]=(clock.rounds[s.step.id]||0)+1;clock.changes.push({at:s.elapsed,reason:`AMRAP: ${n} ${b.items[(amrapIndex-1)%b.items.length].reps?'repetições':'segundos'} em ${b.items[(amrapIndex-1)%b.items.length].exercise.name}`})}else{clock.completedReps[s.step.id]=n;if(s.step.format==='emom'){
 if(!clock.completedSteps.includes(s.step.id))clock.completedSteps.push(s.step.id);
 // Finish early within the minute: the remaining execution budget becomes rest without advancing global time.
 const remaining=s.step.end-s.elapsed;if(remaining>0){const split=Math.max(0,s.elapsed-s.step.start);const rest=clock.plan.timeline[s.index+1];s.step.duration=split;s.step.end=s.elapsed;if(rest?.kind==='rest'){rest.start=s.elapsed;rest.duration=rest.end-rest.start}clock.lastIndex=-1;clock.changes.push({at:s.elapsed,reason:'EMOM: execução confirmada; restante minuto para descanso.'})}
 }}modal.close();await audio.unlock();clock.resume();requestWake();checkpoint();paintedStep=''}
 else if(form.id==='summary-form'){summary.plan.name=String(f.get('name')).trim()||summary.plan.name;summary.rating=rating;summary.notes=String(f.get('notes'));summary.plan.notes=summary.notes;summary.plan.rating=rating;summary.plan.favorite=f.has('favorite');if(save(s=>{const h=s.history.findIndex(h=>h.id===summary.id);if(h>=0)s.history[h]=structuredClone(summary);else s.history.unshift(structuredClone(summary));const p=s.saved.findIndex(p=>p.id===summary.plan.id);if(p>=0)s.saved[p]=structuredClone(summary.plan);else s.saved.unshift(structuredClone(summary.plan))})){page='saved';render();toast('Treino e avaliação guardados.')}}
 }catch(err){const error=document.getElementById('edit-error');if(form.id==='edit-form'&&error)error.textContent=err.message;else toast(err.message);console.error(err)}}
app.addEventListener('input',e=>{if(e.target.id==='search'){const selection=e.target.selectionStart;search=e.target.value;render({scroll:false});const input=document.getElementById('search');input.focus();input.setSelectionRange(selection,selection)}});
app.addEventListener('change',e=>{if(e.target.id==='only-favorites'){onlyFavorites=e.target.checked;render({scroll:false})}if(e.target.id==='plan-name'){updatePlanName();persistPlan()}});
content.addEventListener('change',async e=>{if(e.target.closest('#counter-settings-form')){counterCommand(document.getElementById('counter-panel'),'settings',{voice:document.querySelector('#counter-settings-form [name=voice]').checked,beeps:document.querySelector('#counter-settings-form [name=beeps]').checked});return}if(e.target.id!=='import-file'||!e.target.files[0])return;await importAllData(e.target.files[0]);e.target.value=''});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
window.addEventListener('pagehide',()=>{if(clock&&page==='active')checkpoint()});
document.addEventListener('visibilitychange',()=>{if(page!=='active')return;if(document.hidden){audio.stop();checkpoint()}else{if(clock.running){audio.unlock().catch(()=>{});requestWake()}clock.lastIndex=-1;clock.lastSecond=-1;paintedStep=''}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
window.addEventListener('online',()=>toast('Ligação restabelecida. Os teus dados continuam no dispositivo.'));
render();

function dataAccessButton(){return btn('manageData',`${icon('download')} Exportar / importar dados`,'secondary full','style="margin-top:18px"')}
function backupControls(){const workouts=store.state.history.filter(h=>h.status==='completed').length,counterWorkouts=store.state.fittempo?.history?.length||0;return `<div class="details-label">Cópia de segurança · toda a app</div><p class="small" style="margin:8px 0">Treinos guardados: ${store.state.saved.length} · ${workouts} treino${workouts===1?'':'s'} Crossfit · ${counterWorkouts} treino${counterWorkouts===1?'':'s'} FitTempo · ${store.state.favorites.length} exercícios favoritos</p><p class="small muted">Inclui os treinos guardados, favoritos dos exercícios, histórico, notas e definições do Crossfit e do FitTempo. Importar junta os registos sem duplicar, mantém a sessão atual e recupera as definições do ficheiro.</p>${btn('export',`${icon('download')} Exportar dados`,'secondary full','style="margin-top:12px"')}${btn('importBackup',`${icon('upload')} Importar dados`,'secondary full','style="margin-top:10px"')}<input type="file" id="import-file" accept=".json,application/json" class="hidden">`}
async function currentCounterData(){
 const live=await requestCounterBackup(document.getElementById('counter-panel'));
 if(live){validateFitTempo(live);return live}
 if(store.state.fittempo)return structuredClone(store.state.fittempo);
 try{const history=JSON.parse(localStorage.getItem('fittempo_history')||'[]');return validateFitTempo({history})}catch{throw Error('Não foi possível ler os dados do FitTempo. Abre o FitTempo e tenta novamente.')}
}
async function exportAllData(){
 if(clock)checkpoint();
 const fittempo=await currentCounterData();
 const snapshot={...store.state,generatorConfig:structuredClone(config),fittempo,unsavedSummary:summary||store.state.unsavedSummary||null};
 const blob=new Blob([JSON.stringify(makeBackup(snapshot,APP_VERSION),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');
 link.href=url;link.download=`bodywod-completo-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Cópia JSON de Crossfit e FitTempo exportada.');
}
async function importAllData(file){
 try{
 if(file.size>100e6)throw Error('Backup demasiado grande (máximo 100 MB).');
 const incoming=parseBackup(await file.text());
 const currentFitTempo=await currentCounterData();
 const merged=mergeBackup({...store.state,fittempo:currentFitTempo},incoming);
 if(merged.session)merged.session.wasRunning=false;
 const durable=save(s=>Object.assign(s,merged));
 if(incoming.generatorConfig)config={...config,...incoming.generatorConfig};
 summary=store.state.unsavedSummary||summary;plan=clock?.plan||store.state.lastPlan;
 if(incoming.fittempo)restoreCounterBackup(document.getElementById('counter-panel'),merged.fittempo);
 audio.refreshVoices();modal.close();render({scroll:false});toast(durable?'Backup importado. Registos reunidos sem duplicados.':'Backup importado apenas em memória. Exporta antes de fechar.');
 }catch(error){toast(error.message||'Não foi possível importar o backup.');}
}
window.addEventListener('message',event=>{
 const frame=document.getElementById('counter-frame');if(event.source!==frame?.contentWindow)return;
 if(!['bodywod-counter-data-ready','bodywod-counter-data-changed'].includes(event.data?.type))return;
 try{
 const incoming=validateFitTempo(event.data.data);
 if(event.data.type==='bodywod-counter-data-ready'&&store.state.fittempo){
 const combined=mergeFitTempo(incoming,store.state.fittempo);save(s=>{s.fittempo=combined});restoreCounterBackup(document.getElementById('counter-panel'),combined);
 }else save(s=>{s.fittempo=incoming});
 }catch{toast('Não foi possível sincronizar os dados do FitTempo.');}
});
